"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["4026"],{33909(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.pagina_codigo_invalido","status":422,"titulo":"O c\xf3digo da p\xe1gina \xe9 obrigat\xf3rio e tem tamanho limitado"},"descricao":{"codigo":"uniplus.estrutura_formulario.pagina_codigo_invalido","requisitos":[],"oQueAconteceu":["O `codigo` da p\xe1gina est\xe1 vazio, excede 60 caracteres ou est\xe1 fora do formato. A mensagem \xe9 \\"O c\xf3digo da p\xe1gina \xe9 obrigat\xf3rio, come\xe7a com letra mai\xfascula e tem s\xf3 letras mai\xfasculas, algarismos e sublinhados isolados, at\xe9 60 caracteres.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `paginas[i].codigo`; nos modelos de formul\xe1rio o caminho come\xe7a por `conteudo.paginas`. Nada \xe9 gravado. Cada p\xe1gina recusada tem a pr\xf3pria entrada, junto das demais recusas da forma da p\xe1gina (t\xedtulo, ordem, descri\xe7\xe3o, aviso e exibi\xe7\xe3o).","A recusa vale para o texto presente. A propriedade `codigo` ausente ou nula \xe9 recusada antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo. H\xe1 ainda um caso s\xf3 da grava\xe7\xe3o do formul\xe1rio do processo: uma p\xe1gina nula dentro da lista de `paginas` \xe9 recusada com este mesmo c\xf3digo, com `field` igual a `paginas[i]` e a mensagem \\"A p\xe1gina veio nula.\\"; nos modelos, a p\xe1gina nula \xe9 recusada como [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada).","Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Informe em `codigo` um texto de 1 a 60 caracteres, e retire da lista a p\xe1gina nula, se houver. O c\xf3digo \xe9 o que os itens usam em `paginaCodigo`."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);